# Zero-look-ahead 3-candle swing detector
# Confirmed only at the close of candle index i (which acts as C3)

def detect_swings(candles):
    # Each bar has explicit open_time, close_time and is_closed fields.
    # Keep neighboring bars consecutive; skip an unfinished three-bar window.
    swings = []
    # Start at index 2 so i-2 (C1), i-1 (C2), and i (C3) all exist
    for i in range(2, len(candles)):
        c1 = candles[i - 2]
        c2 = candles[i - 1]
        c3 = candles[i]
        if not all(bar.is_closed for bar in (c1, c2, c3)):
            continue

        # Strict 3-Candle Swing High
        if c2.high > c1.high and c2.high > c3.high:
            swings.append({
                "type": "SWING_HIGH",
                "price": c2.high,
                "pivot_time": c2.open_time,
                "confirmed_at": c3.close_time
            })

        # Strict 3-Candle Swing Low
        if c2.low < c1.low and c2.low < c3.low:
            swings.append({
                "type": "SWING_LOW",
                "price": c2.low,
                "pivot_time": c2.open_time,
                "confirmed_at": c3.close_time
            })
    return swings
